const icons={pen:'<path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/><path d="m4 15 5 5"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M8 13h8m-8 4h5"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1zm0 0v15"/><path d="M5 8h3m-3 4h3m8-4h3m-3 4h3"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',crown:'<path d="m3 6 4 4 5-6 5 6 4-4-3 13H6zM7 22h10"/>',play:'<path d="m8 4 12 8-12 8z"/>',scan:'<path d="M8 3H5a2 2 0 0 0-2 2v3m13-5h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3m8 0h3a2 2 0 0 0 2-2v-3"/><circle cx="11" cy="11" r="4"/><path d="m14 14 3 3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',edit:'<path d="M12 4H5v16h15v-8M16 3l5 5-9 9H7v-5z"/><path d="m13 6 5 5"/>',presentation:'<path d="M3 3h18v13H3zM12 16v5m-5 0 5-5 5 5M7 12l3-3 3 2 4-5"/>',chart:'<path d="M4 3v18h17M8 16v-4m5 4V6m5 10V9"/><circle cx="8" cy="8" r="1"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',cap:'<path d="m2 9 10-6 10 6-10 6zM6 12v6c4 3 8 3 12 0v-6M22 9v8"/>',send:'<path d="m21 3-7 19-4-9-8-4zM10 13 21 3"/>'};
const svg=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=svg(el.dataset.icon));}
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dialog=$('#home-dialog');let previousFocus=null;
function toast(text){$('#home-toast').textContent=text;$('#home-toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#home-toast').classList.remove('visible'),3000);}
function openDialog(title,html){previousFocus=document.activeElement;$('#home-dialog-title').textContent=title;$('#home-dialog-body').innerHTML=html;hydrate(dialog);dialog.showModal();document.body.classList.add('home-modal-open');}
function closeDialog(){dialog.close();}
dialog.addEventListener('close',()=>{document.body.classList.remove('home-modal-open');previousFocus?.focus();});$('#dialog-close').addEventListener('click',closeDialog);
dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();});
const examples={outline:{title:'论文大纲 · 结构示例',selector:'.mini-outline',note:'这是本地模板的结构示例。请结合真实研究完善章节、证据与引用；当前未调用 AI 生成正文。',url:'/workspace.html#category/writing',action:'开始创建论文'},report:{title:'查重报告 · 界面示例',selector:'.mini-comparison',note:'这里展示的是相似片段与对照正文的呈现方式，不是一次实际检测结果。正式体验会根据当前本地材料计算文本匹配，未接入全网检索。',url:'/workspace.html#category/detection',action:'上传论文体验'},revision:{title:'修改任务 · 模板示例',selector:'.mini-revision',note:'这是通用修改清单示例，未解析导师批注或执行 AI 修改。你可以进入工作台填写导师意见，整理、编辑和保存任务模板。',url:'/workspace.html#tool/review',action:'整理修改任务'}};
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{const e=examples[b.dataset.example];openDialog(e.title,`<p>${e.note}</p><div class="example-modal-preview">${$(e.selector).outerHTML}</div><div class="home-dialog-actions"><a class="button" href="${e.url}">${e.action} ${svg('arrow')}</a></div>`);}));
$('#status-button').addEventListener('click',()=>{openDialog('PaperKnow 功能状态',`<p>当前是本地体验版。以下状态反映实际可使用范围，服务接入后会更新说明。</p><div class="status-list">${[['论文写作','大纲模板、编辑、保存与导出','本地可用'],['文档解析','DOCX、文本型 PDF、UTF-8 TXT；扫描 PDF 暂无 OCR','本地可用'],['论文查重','对照导入正文，比对片段并展示来源；不是全网正式查重','本地可用'],['科研绘图','根据实际数据生成多系列图表，导出 SVG / PNG / CSV','本地可用'],['修改、排版与 PPT','手动修改与版本保存、DOCX 排版副本、可编辑 PPTX 导出','本地可用'],['文献研读','正文阅读、手动笔记与译文整理；AI 尚未接入','本地可用'],['AI 写作、改写与翻译','尚未接入模型，不生成真实 AI 服务结果','待开放'],['全网检索与 AI 率检测','尚未接入在线数据库或检测服务','待开放']].map(([t,d,s])=>`<div><div><b>${t}</b><small>${d}</small></div><span class="status-tag ${s==='待开放'?'neutral':''}">${s}</span></div>`).join('')}</div><div class="home-dialog-actions"><a class="button" href="/workspace.html">进入工作台 ${svg('arrow')}</a></div>`);});
$('#about-button').addEventListener('click',()=>openDialog('关于 PaperKnow','<p>PaperKnow 面向专科、本科、硕士、博士及科研人员，帮助整理从选题、开题到写作、修改和成果输出的工作流程。</p><p>当前为本地开发体验版，尚未开放正式账号、支付与在线 AI 服务。真实服务范围与数据处理说明将在上线前公布。</p><div class="home-dialog-actions"><a class="button outline" href="/workspace.html#help">查看使用帮助</a><a class="button" href="/workspace.html">开始体验</a></div>'));
function profile(){try{const p=JSON.parse(localStorage.getItem('paperknow-local-profile')||'null');return p&&typeof p.name==='string'?p:null;}catch{return null;}}
function renderAccount(){const p=profile();$('#account-button').textContent=p?p.name.slice(0,6):'登录';$('#account-button').setAttribute('aria-label',p?'管理本地昵称':'登录本地体验');}
$('#account-button').addEventListener('click',()=>{const p=profile();openDialog('你的本地体验空间',`<p>设置昵称即可开始本地体验，不需要真实账号或密码。正式登录服务尚未接入。</p><form class="local-login-form" id="local-login-form"><label for="local-nickname">你的昵称</label><input id="local-nickname" maxlength="20" required placeholder="例如：正在写论文的小林" value="${esc(p?.name||'')}"><p id="login-error" role="alert"></p><button class="button" type="submit">保存昵称</button></form>${p?'<button class="text-button" id="local-logout">退出本地体验</button>':''}`);$('#local-login-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#local-nickname').value.trim();if(!name){$('#login-error').textContent='请输入昵称。';return;}try{localStorage.setItem('paperknow-local-profile',JSON.stringify({...profile(),name}));renderAccount();closeDialog();toast('昵称已保存，可以进入工作台。');}catch{$('#login-error').textContent='浏览器无法保存昵称，你仍可直接进入工作台。';}});$('#local-logout')?.addEventListener('click',()=>{try{localStorage.removeItem('paperknow-local-profile');renderAccount();closeDialog();}catch{toast('暂时无法更新本地昵称。');}});});
function closeMenus(){ $('#more-menu').hidden=true;$('#more-button').setAttribute('aria-expanded','false');$('#main-nav').classList.remove('mobile-open');$('#mobile-menu').setAttribute('aria-expanded','false');}
$('#more-button').addEventListener('click',()=>{const hidden=!$('#more-menu').hidden;$('#more-menu').hidden=hidden;$('#more-button').setAttribute('aria-expanded',String(!hidden));});
$('#mobile-menu').addEventListener('click',()=>{const open=$('#main-nav').classList.toggle('mobile-open');$('#mobile-menu').setAttribute('aria-expanded',String(open));});
document.addEventListener('click',e=>{if(!e.target.closest('.more-wrap')){$('#more-menu').hidden=true;$('#more-button').setAttribute('aria-expanded','false');}if(e.target.closest('#main-nav a'))closeMenus();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenus();});
// Preserve old saved-draft and tool URLs while routing them to the unified workspace.
const params=new URLSearchParams(location.search);const legacy=params.get('tool'),draft=params.get('draft');const ids=['writing','topic','proposal','summary','course','review','rewrite','reduce','aigc','reading','search','translation','ppt','format','journal','resume','research'];if(draft&&/^\d+$/.test(draft))location.replace('/workspace.html#draft/'+encodeURIComponent(draft));else if(legacy==='check')location.replace('/workspace.html#category/detection');else if(ids.includes(legacy))location.replace('/workspace.html#tool/'+legacy);
if(location.hash==='#writing')location.replace('/workspace.html#category/writing');
hydrate();renderAccount();
